package method_Basic_Practice;

public class FormatingAling_3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

	  System.out.printf("%-10s%s%n", "Number", "Value");
	  System.out.printf("%-10s%s%n", "------", "-----");
	  
	  
	  System.out.printf("%-10d%d",   1, 10);
	  System.out.printf("%-10d%n", 2, 200);
	  System.out.printf("%-10d%d%n", 3, 3000);
	  System.out.printf("%-10d%d%n", 4, 4000);
	}
}
	  